class Solution:
    def binarySearch(self, nums: List[int], target: int, lower):
        l, r, ans = 0, len(nums) -1, len(nums)
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] > target or (lower and nums[mid] >= target):
                r = mid - 1
                ans = mid
            else:
                l = mid + 1
        return ans 

    def searchRange(self, nums: List[int], target: int) -> List[int]:
        leftIdx = self.binarySearch(nums, target, True)
        rightIdx = self.binarySearch(nums, target, False) - 1
        if leftIdx <= rightIdx and rightIdx < len(nums) and nums[leftIdx] == target and nums[rightIdx] == target:
            return [leftIdx, rightIdx]
        return [-1,-1]

class Solution:
    def binarySearch(self, nums, target):
        l, r = 0, len(nums) - 1

        while l <= r:
            mid = (l + r) // 2
            if nums[mid] * nums[mid] < target:
                l = mid + 1
            elif nums[mid] * nums[mid] > target:
                r = mid - 1
            else:
                return mid
        return r

    def mySqrt(self, x: int) -> int:
        if x == 0 or x == 1: return x
        target = x
        nums = range(x//2 + 1)
        ans = self.binarySearch(nums, target)
        return ans 

