class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        # if num == 0 or num == 1: return True
        l, r = 0, num #这里和普通的二分不太一样，这样的条件才能把边界（0，1）考虑进去

        while l <= r:
            mid = (l + r) // 2
            if mid * mid < num:
                l = mid + 1
            elif mid * mid > num:
                r = mid - 1
            else:
                return True

        return False

class Solution:
    def removeElement(self, nums: List[int], val: int) -> int:
        low = fast = 0
        for fast in range(len(nums)):
            if nums[fast] != val:
                nums[low] = nums[fast]
                low += 1
        return low

class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        low = 0
        for fast in range(1, len(nums)):
            if nums[low] != nums[fast]:
                low += 1
                nums[low] = nums[fast]
        return low + 1

class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        low = 0
        for fast in range(1, len(nums)):
            if nums[fast] != 0 and nums[low] == 0:
                nums[low] = nums[fast]
                nums[fast] = 0 # nums[left], nums[right] = nums[right], nums[left]
                low += 1
            elif nums[low] != 0:
                low += 1

class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        i, j = len(s) - 1, len(t) - 1
        skipS = skipT = 0

        while i >= 0 or j >= 0:
            while i >= 0:
                # 如果是 # 就增加一个需要退格（跳过）的数量，然后把指针向前移动一个
                if s[i] == '#':
                    skipS += 1
                    i -= 1
                # 如果需要退格，就消耗一个标记，然后直接把指针向前移动一个
                elif skipS > 0:
                    skipS -= 1
                    i -= 1
                else:
                    break # 推出进行另外一个字符串的遍历或者判断
            while j >= 0:
                if t[j] == '#':
                    skipT += 1
                    j -= 1
                elif skipT > 0:
                    skipT -= 1
                    j -= 1
                else:
                    break
            # 都跳出循环之后的判断
            # 判断当前是否相等，不相等直接结束
            if i >= 0 and j >= 0:
                if s[i] != t[j]:
                    return False
            elif i >= 0 or j >= 0: # 上诉条件不成立，这个条件成立的话，就说明，有一个字符串遍历完成了，另外一个没有，所以后续长度不相等，直接退出
                return False

            # 跳出训练之后也要将指针向后移动
            i -= 1
            j -= 1
        return True

class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ans = [0] * n

        i, j, pos = 0, n-1, n-1
        while i <= j:
            if nums[i] * nums[i] > nums[j] * nums[j]:
                ans[pos] = nums[i] * nums[i]
                i += 1
            else:
                ans[pos] = nums[j] * nums[j]
                j -= 1
            pos -= 1
        return ans

from typing import List
from collections import Counter


class Solution:
    def totalFruit(self, fruits: List[int]) -> int:
        cnt = Counter()

        left = ans = 0
        for right, x in enumerate(fruits):
            cnt[x] += 1
            while len(cnt) > 2:
                cnt[fruits[left]] -= 1
                if cnt[fruits[left]] == 0:
                    cnt.pop(fruits[left])
                left += 1
            ans = max(ans, right - left + 1)

        return ans
